    /*
     * Add to the Batches
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Shipment
     */
    public Shipment addToBatches( UUID parentId, List<UUID> children ) {
	    LOGGER.info("handling AssignBatchesToShipmentEvent - " );
	    
	    Shipment parentEntity = repository.findById(parentId).get();

		for (UUID childId : children) {
			HarvestBatch child = registry.project(HarvestBatch.class, childId);
			parentEntity.getBatches().add(child);
		}

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

